async function main() {
  await mongoose.connect(process.env.MONGODB_URI);
  const db = mongoose.connection.db;

  // Find or create the Grade 8
  let gradeDoc = await db.collection('grades').findOne({ name: /Grade 8/i, schoolId: SCHOOL_ID });
  let GRADE_ID;
  if (gradeDoc) {
    GRADE_ID = gradeDoc._id;
    console.log('Found Grade 8:', String(GRADE_ID));
  } else {
    const result = await db.collection('grades').insertOne({
      name: 'Grade 8', schoolId: SCHOOL_ID, orderIndex: 8,
      isDeleted: false, createdAt: new Date(), updatedAt: new Date(),
    });
    GRADE_ID = result.insertedId;
    console.log('Created Grade 8:', String(GRADE_ID));
  }

  // Find or create the Social Sciences subject
  const subjectDoc = await db.collection('subjects').findOne({ name: /Social.*Sci/i, schoolId: SCHOOL_ID });

  let SUBJECT_ID;
  if (subjectDoc) {
    SUBJECT_ID = subjectDoc._id;
    console.log('Found Social Sciences subject:', String(SUBJECT_ID));
  } else {
    const result = await db.collection('subjects').insertOne({
      name: 'Social Sciences',
      code: 'SS',
      schoolId: SCHOOL_ID,
      isDeleted: false,
      createdAt: new Date(),
      updatedAt: new Date(),
    });
    SUBJECT_ID = result.insertedId;
    console.log('Created Social Sciences subject:', String(SUBJECT_ID));
  }

  const now = new Date();
  const baseDoc = {
    schoolId: SCHOOL_ID,
    createdBy: CREATED_BY,
    gradeId: GRADE_ID,
    subjectId: SUBJECT_ID,
    type: 'lesson',
    status: 'approved',
    isDeleted: false,
    createdAt: now,
    updatedAt: now,
    __v: 0,
  };

  const chapters = [
    {
      title: 'Chapter 1: The Industrial Revolution in Britain and Southern Africa (History)',
      description: 'Changes during the Industrial Revolution in Britain, the economy before industrialisation, social changes, urbanisation, child labour, trade unions, and the connection to southern Africa including the discovery of diamonds and diamond mining at Kimberley.',
      order: 1,
      lessons: [
        { title: 'Changes During the Industrial Revolution in Britain', description: 'What was the Industrial Revolution, the domestic system, enclosure, social changes, urbanisation, factory conditions, child labour, trade unions, and the growth of British power.', blocks: ch1_lesson1, term: 1 },
        { title: 'Southern Africa Before 1860 and Diamond Mining in Kimberley', description: 'Southern Africa before the mineral revolution, discovery of diamonds, diamond mining at Kimberley, Cecil Rhodes and De Beers, the compound system, pass laws, and conditions for black workers.', blocks: ch1_lesson2, term: 1 },
      ],
    },
    {
      title: 'Chapter 2: Maps and Globes (Geography)',
      description: 'Types of maps, scale, calculating distances, the globe, latitude and longitude, hemispheres, time zones, satellite images, reading satellite imagery, and satellite technology in South Africa.',
      order: 2,
      lessons: [
        { title: 'Maps, Atlases, and the Globe', description: 'Types of maps, map scales (word, ratio, line), calculating distances, large-scale vs small-scale maps, the globe, latitude and longitude, coordinates, and time zones.', blocks: ch2_lesson1, term: 1 },
        { title: 'Satellite Images', description: 'How satellite images are taken, true-colour vs false-colour images, identifying features, uses of satellite images (weather, environment, agriculture), and satellite technology in South Africa.', blocks: ch2_lesson2, term: 1 },
      ],
    },
    {
      title: 'Chapter 3: The Mineral Revolution in South Africa (History)',
      description: 'The mineral revolution as a turning point, increasing labour control (pass system, compounds, contract labour), land dispossession, the defeat of African kingdoms, migrant labour, gold mining on the Witwatersrand, the Randlords, the colour bar, and labour resistance.',
      order: 3,
      lessons: [
        { title: 'Britain, Diamond Mining, and Increasing Labour Control', description: 'The mineral revolution, pass system, compound system, contract labour, land dispossession, defeat of African kingdoms, migrant labour\'s impact on families, and indentured Indian labour in Natal.', blocks: ch3_lesson1, term: 2 },
        { title: 'Deep-Level Gold Mining on the Witwatersrand', description: 'Discovery of gold in 1886, birth of Johannesburg, the Randlords, Chamber of Mines, working conditions, the colour bar, forms of labour resistance, and the mineral revolution as a turning point.', blocks: ch3_lesson2, term: 2 },
      ],
    },
    {
      title: 'Chapter 4: Climate Regions (Geography)',
      description: 'Weather vs climate, factors influencing temperature and rainfall in South Africa (latitude, ocean currents, altitude, relief), climate regions of the world, biomes, climate change, and the relationship between climate and human activity.',
      order: 4,
      lessons: [
        { title: 'Factors That Influence Temperature and Rainfall in South Africa', description: 'Weather vs climate, elements of weather, distance from the Equator (latitude), distance from the sea and ocean currents (Agulhas and Benguela), altitude, mountains and rain shadow, and South Africa\'s climate summary.', blocks: ch4_lesson1, term: 2 },
        { title: 'Climate Regions Around the World', description: 'Major climate zones (tropical, subtropical, temperate, continental, polar), detailed climate types, links between climate and factors, climate and vegetation (biomes), climate change, and climate and human activity.', blocks: ch4_lesson2, term: 2 },
      ],
    },
    {
      title: 'Chapter 5: The Scramble for Africa (History)',
      description: 'The impact of the transatlantic slave trade, causes of the scramble for Africa, the Berlin Conference (1884-1885), patterns and results of colonisation, resistance to colonisation, and the case study of the Ashanti Kingdom.',
      order: 5,
      lessons: [
        { title: 'European Colonisation of Africa in the Late 19th Century', description: 'The transatlantic slave trade and its impact, causes of European colonisation (economic, political, technological, ideological), the Berlin Conference, patterns of colonisation, African resistance, and results of colonisation.', blocks: ch5_lesson1, term: 3 },
        { title: 'Case Study: The Ashanti Kingdom', description: 'The Ashanti Kingdom\'s origins and political organisation, European contact on the Gold Coast, the Anglo-Ashanti wars, Yaa Asantewaa and resistance, and the results of colonisation for the Ashanti.', blocks: ch5_lesson2, term: 3 },
      ],
    },
    {
      title: 'Chapter 6: Settlement (Geography)',
      description: 'Types of settlements, rural vs urban, rural settlement patterns, urban settlements and the apartheid city model, land use zones, urbanisation, push and pull factors, problems of rapid urbanisation, and solutions.',
      order: 6,
      lessons: [
        { title: 'Rural and Urban Settlements', description: 'Types of settlements, rural vs urban, rural settlement patterns (isolated, linear, nucleated, dispersed), urban settlements and the apartheid city model, land use zones, and identifying land use on aerial photographs.', blocks: ch6_lesson1, term: 3 },
        { title: 'Urbanisation', description: 'What is urbanisation, push and pull factors, urbanisation in South Africa\'s historical context, problems of rapid urbanisation (housing, services, unemployment), social issues, and solutions.', blocks: ch6_lesson2, term: 3 },
      ],
    },
    {
      title: 'Chapter 7: World War I (History)',
      description: 'Causes of World War I (MAIN — Militarism, Alliances, Imperialism, Nationalism), the assassination of Archduke Franz Ferdinand, trench warfare, new weapons, conscription, South Africa\'s role, women during WWI, and the Treaty of Versailles.',
      order: 7,
      lessons: [
        { title: 'Reasons Why World War I Broke Out', description: 'Background to WWI, nationalism, imperialism, militarism, the alliance systems, the assassination of Archduke Franz Ferdinand, the chain reaction to war, and the naval arms race.', blocks: ch7_lesson1, term: 4 },
        { title: 'Experiences in World War I and Women During WWI', description: 'Trench warfare on the Western Front, new weapons and technology, conscription and conscientious objectors, South Africa in WWI (Delville Wood, SS Mendi), women\'s changing roles, Emmeline Pankhurst, and the Treaty of Versailles.', blocks: ch7_lesson2, term: 4 },
      ],
    },
    {
      title: 'Chapter 8: Transport and Trade (Geography)',
      description: 'What is trade, imports and exports, modes of transport (road, rail, sea, air), South Africa\'s trade and transport, harbours and shipping, urban transport systems, transport issues, and sustainable transport for the future.',
      order: 8,
      lessons: [
        { title: 'Trade and Transport Around the World and in South Africa', description: 'What is trade, imports and exports, modes of transport, South Africa\'s exports and imports, trading partners, major transport routes, Durban harbour case study, and future transport requirements.', blocks: ch8_lesson1, term: 4 },
        { title: 'People and Transport in Urban Areas', description: 'Public transport in SA cities, minibus taxis, transport issues (congestion, cost, safety), private transport, BRT systems, integrated transport, and sustainable transport for the future.', blocks: ch8_lesson2, term: 4 },
      ],
    },
  ];

  const textbookChapters = [];
  let totalLessons = 0;

  for (const ch of chapters) {
    const resourceIds = [];
    for (const lesson of ch.lessons) {
      const res = await db.collection('contentresources').insertOne({
        ...baseDoc,
        title: lesson.title,
        description: lesson.description,
        blocks: lesson.blocks,
        term: lesson.term,
        curriculumNodeId: null,
      });
      resourceIds.push(res.insertedId);
      totalLessons++;
      console.log('  Inserted: ' + lesson.title + ' (' + lesson.blocks.length + ' blocks)');
    }

    textbookChapters.push({
      id: new mongoose.Types.ObjectId().toString(),
      title: ch.title,
      description: ch.description,
      order: ch.order,
      curriculumNodeId: null,
      resources: resourceIds.map(function (id, i) { return { resourceId: id, order: i }; }),
    });
  }

  // Create textbook
  const textbook = await db.collection('textbooks').insertOne({
    title: 'Grade 8 Social Sciences \u2014 CAPS Textbook',
    description: 'Complete CAPS-aligned textbook covering History (The Industrial Revolution, The Mineral Revolution in South Africa, The Scramble for Africa, World War I) and Geography (Maps and Globes, Climate Regions, Settlement, Transport and Trade) for the Grade 8 Social Sciences curriculum.',
    schoolId: SCHOOL_ID,
    gradeId: GRADE_ID,
    subjectId: SUBJECT_ID,
    status: 'published',
    chapters: textbookChapters,
    createdBy: CREATED_BY,
    isDeleted: false,
    createdAt: now,
    updatedAt: now,
    __v: 0,
  });

  console.log('\n========================================');
  console.log('  TEXTBOOK: Grade 8 Social Sciences');
  console.log('  ID: ' + String(textbook.insertedId));
  console.log('  Chapters: ' + textbookChapters.length);
  console.log('  Lessons: ' + totalLessons);
  console.log('========================================');

  await mongoose.disconnect();
}

main().catch(function (err) { console.error(err); process.exit(1); });
